import {execFileSync} from 'node:child_process';import {mkdtempSync,chmodSync,rmSync,existsSync} from 'node:fs';import {tmpdir} from 'node:os';import {join,resolve} from 'node:path';
/** Test-only local SDK build; production startup never invokes a compiler. */
export function buildNativePower(){const directory=mkdtempSync(join(process.env.HUB_TEST_TMPDIR??tmpdir(),'hub-native-power-')),executable=join(directory,'power-observer');try{execFileSync('xcrun',['clang','-std=c11','-O2','-Wall','-Wextra','-Werror',resolve('native/macos-power.c'),'-framework','IOKit','-framework','CoreFoundation','-o',executable],{stdio:'pipe',timeout:20000});chmodSync(executable,0o700);return {executable,resources:()=>({exists:existsSync(directory)}),close:()=>rmSync(directory,{recursive:true,force:true})};}catch(cause){rmSync(directory,{recursive:true,force:true});throw new Error('native power test build failed',{cause});}}
